function lecture(id, skillId, objectives, sections, workedExamples, misconceptions, checks) {
  return { id, skillId, objectives, sections, workedExamples, misconceptions, checks, assets: [] };
}

function question(id, skillId, difficulty, stem, options, answerIndex, reasons, reviews, cognitiveProcess, representationType, misconceptionTargets) {
  return { id, skillId, difficulty, stem, options, answerIndex, reasons, reviews, cognitiveProcess: Array.isArray(cognitiveProcess) ? cognitiveProcess : [cognitiveProcess], representationType, misconceptionTargets, assets: [] };
}

function stimulus(id, skillId, type, content, summary, dataFallback, questions) {
  return { id, skillId, type, content, accessibility: { summary, colorIndependent: true, dataFallback }, questions, assets: [] };
}

